package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import htsjdk.samtools.reference.*;
import org.jlinalg.genetics.VepVcf;
import org.jlinalg.sequence.FastaIndexes;
import static org.jlinalg.cli.SeuratDifferentialContracts.*;

/** Complete immutable VCF/gene captures and explicit unchanged external FASTA/index bindings. */
final class SpliceAiToolsInputs {
    private SpliceAiToolsInputs(){ }
    record Binding(Path original,Path captured,Map<String,Object> pin){void verify()throws IOException{if(!pin.equals(SpliceAiToolsFiles.pin(original,Long.MAX_VALUE))||(captured!=null&&!pin.equals(SpliceAiToolsFiles.pin(captured,Long.MAX_VALUE))))throw new IOException("Original/captured SpliceAI input or resource changed: "+original);}}
    record Prepared(Path original,Path annotated,Path fasta,Path fai,String annotation,Map<String,Object> captured,List<Binding> bindings,Map<String,Object> summary){void verify()throws IOException{for(var binding:bindings)binding.verify();}}
    static Prepared prepare(Path root,Path parent,Map<String,Object> raw,Map<String,Object> r,SpliceAiToolsRuntime.Prepared runtime)throws IOException {
        var bindings=new ArrayList<Binding>();var captured=new LinkedHashMap<String,Object>(raw);captured.put("out",".");long[] remaining={SpliceAiToolsRequest.number(r,"maximum_input_bytes")};Path original=null,annotated=null,fasta=null,fai=null;String annotation=null;Map<String,Object> summary=Map.of();
        if(text(r,"backend").equals("NATIVE")){
            annotated=capture(root,parent,raw,"annotated_vcf","annotated.vcf",remaining,bindings,captured);
            if(raw.containsKey("original_vcf"))original=capture(root,parent,raw,"original_vcf","original.vcf",remaining,bindings,captured);
        }else{
            original=capture(root,parent,raw,"input_vcf","original.vcf",remaining,bindings,captured);captured.put("runtime",runtime.root().toString());var reference=object(r.get("reference"),"reference");var savedReference=new LinkedHashMap<String,Object>(reference);long[] resources={SpliceAiToolsRequest.number(r,"maximum_resource_bytes")};var resourceIdentities=new LinkedHashMap<String,Object>();
            fasta=external(parent,reference,"fasta","fasta_sha256",resources,bindings,resourceIdentities);fai=external(parent,reference,"fai","fai_sha256",resources,bindings,resourceIdentities);if(!fai.equals(Path.of(fasta+".fai")))throw new IOException("Original pyfaidx requires the explicit index beside this exact FASTA at FASTA.fai; no replacement or generated external index");FastaIndexes.validate(fasta,fai);savedReference.put("fasta",fasta.toString());savedReference.put("fai",fai.toString());captured.put("reference",savedReference);copy(fai,root.resolve("inputs/reference.fai"),resources,bindings);
            var a=object(r.get("annotation"),"annotation");String kind=text(a,"kind");Path geneTable;
            if(kind.equals("provided")){Path file=resolve(parent,text(a,"file"));geneTable=copy(file,root.resolve("inputs/annotation.tsv"),resources,bindings);var savedAnnotation=new LinkedHashMap<String,Object>(a);savedAnnotation.put("file","inputs/annotation.tsv");captured.put("annotation",savedAnnotation);annotation=geneTable.toString();}
            else{String key=kind.equals("bundled-GENCODE24lift37")?"grch37":"grch38";geneTable=copy(runtime.root().resolve("lib/python3.7/site-packages/spliceai/annotations/"+key+".txt"),root.resolve("inputs/annotation.tsv"),resources,bindings);annotation=key;}
            var geneSummary=validateAnnotation(geneTable,r);json(root.resolve("annotation-summary.json"),geneSummary);json(root.resolve("resource-bindings.json"),Map.of("reference",resourceIdentities,"reference_bytes_copied_into_bundle",false,"assembly_label_independently_certified",false,"annotation",SpliceAiToolsFiles.pin(geneTable,Long.MAX_VALUE)));
            summary=inspect(original,fasta,fai,root.resolve("reference-checks.tsv"),r);json(root.resolve("input-summary.json"),summary);
        }
        return new Prepared(original,annotated,fasta,fai,annotation,captured,List.copyOf(bindings),summary);
    }
    private static Path external(Path parent,Map<String,Object> ref,String key,String hash,long[] remaining,List<Binding> bindings,Map<String,Object> identities)throws IOException{
        Path file=SpliceAiToolsFiles.required(resolve(parent,text(ref,key)));var pin=SpliceAiToolsFiles.pin(file,remaining[0]);if(!pin.get("sha256").equals(ref.get(hash)))throw new IOException("Declared complete SpliceAI "+key+" SHA256 differs; no reference substitution");remaining[0]-=((Number)pin.get("bytes")).longValue();bindings.add(new Binding(file,null,pin));identities.put(key,Map.of("path",file.toString(),"pin",pin));return file;
    }
    private static Path capture(Path root,Path parent,Map<String,Object> raw,String key,String leaf,long[] remaining,List<Binding> bindings,Map<String,Object> captured)throws IOException{Path file=copy(resolve(parent,text(raw,key)),root.resolve("inputs/"+leaf),remaining,bindings);captured.put(key,"inputs/"+leaf);return file;}
    private static Path copy(Path source,Path target,long[] remaining,List<Binding> bindings)throws IOException{SpliceAiToolsFiles.copy(source,target,remaining[0]);var pin=SpliceAiToolsFiles.pin(target,remaining[0]);remaining[0]-=((Number)pin.get("bytes")).longValue();bindings.add(new Binding(source,target,pin));return target;}
    static String sourceChromosome(String source,String target){if(source.startsWith("chr")&&!target.startsWith("chr")){int first=0,last=source.length();while(first<last&&"chr".indexOf(source.charAt(first))>=0)first++;while(last>first&&"chr".indexOf(source.charAt(last-1))>=0)last--;return source.substring(first,last);}return!source.startsWith("chr")&&target.startsWith("chr")?"chr"+source:source;}
    static Map<String,Object> inspect(Path input,Path fasta,Path fai,Path ledger,Map<String,Object> r)throws IOException {
        try(var lines=new SpliceAiToolsFiles.Lines(input,r)){for(String line;(line=lines.next())!=null;)if(line.startsWith("##INFO=<ID=SpliceAI,"))throw new IOException("Original input already declares SpliceAI; preserve it and supply an explicitly unannotated original, without automatic stripping");}
        var index=new FastaSequenceIndex(fai);String first=index.iterator().next().getContig();long[] ambiguous={0};
        try(var reference=ReferenceSequenceFileFactory.getReferenceSequenceFile(fasta,true,true);var writer=Files.newBufferedWriter(ledger,StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW)){
            SpliceAiToolsFiles.row(writer,"input_row","literal_CHROM","POS","literal_REF","original_source_lookup_CHROM","reference_bases","state");
            var limits=new VepVcf.Limits(SpliceAiToolsRequest.number(r,"maximum_decoded_characters"),SpliceAiToolsRequest.number(r,"maximum_variants"),SpliceAiToolsRequest.number(r,"maximum_annotations"),(int)SpliceAiToolsRequest.number(r,"maximum_line_characters"));
            var population=VepVcf.inspectOriginal(input,limits,v->{var f=v.fields();String chrom=f.get(0),ref=f.get(3),lookup=sourceChromosome(chrom,first);if(!ref.matches("[ACGTN]+"))throw new IOException("Original1.3 compares uppercase reference bases with literal REF; require explicit uppercase ACGTN without repair");var alts=Arrays.asList(f.get(4).split(",",-1));if(new HashSet<>(alts).size()!=alts.size())throw new IOException("Repeated ALT is ambiguous in original allele-only SpliceAI INFO");for(String alt:alts)if(!alt.matches("[ACGTNacgtn]+")&&!Set.of("<NON_REF>",".").contains(alt))throw new SpliceAiToolsRuntime.Unavailable("Literal ALT is unsupported by this complete original neural profile: "+alt+"; dependent analysis skipped without nucleotide recoding");for(String token:f.get(7).split(";",-1))if(token.equals("SpliceAI")||token.startsWith("SpliceAI="))throw new IOException("Input already contains SpliceAI; no stale annotations are retained as fresh predictions");long pos=Long.parseLong(f.get(1)),end;try{end=Math.addExact(pos,ref.length()-1L);}catch(ArithmeticException e){throw new IOException("SpliceAI REF coordinate overflow",e);}String bases;try{bases=new String(reference.getSubsequenceAt(lookup,pos,end).getBases(),StandardCharsets.US_ASCII);}catch(RuntimeException e){throw new IOException("Original source contig lookup or REF bounds unavailable: "+lookup+":"+pos,e);}if(!bases.toUpperCase(Locale.ROOT).equals(ref))throw new IOException("Literal REF mismatch at input row "+v.row()+"; no allele swap, lift-over or correction");String state=ref.contains("N")?"MATCHED_N_BASES_BIOLOGICALLY_UNASSESSABLE":"MATCHED_ORIGINAL_SOURCE_LOOKUP";if(ref.contains("N"))ambiguous[0]++;SpliceAiToolsFiles.row(writer,v.row(),chrom,f.get(1),ref,lookup,bases,state);});
            if(population.variants()==0)throw new IOException("No complete original variant analysis was requested");if(population.alternateAlleles()>SpliceAiToolsRequest.number(r,"maximum_annotations"))throw new IOException("Complete SpliceAI allele capacity exceeded");return Map.of("variants",population.variants(),"alternate_alleles",population.alternateAlleles(),"matched_ambiguous_N_rows",ambiguous[0],"source_chr_prefix_lookup_documented",true,"input_identities_rewritten",false,"reference_index_independently_rebuilt_for_validation",true);
        }
    }
    static Map<String,Object> validateAnnotation(Path table,Map<String,Object> r)throws IOException{
        long rows=0,exons=0;String first=null;try(var lines=new SpliceAiToolsFiles.Lines(table,r)){if(!"#NAME\tCHROM\tSTRAND\tTX_START\tTX_END\tEXON_START\tEXON_END".equals(lines.next()))throw new IOException("Require complete original seven-column annotation table");for(String line;(line=lines.next())!=null;){String[] f=line.split("\t",-1);if(f.length!=7||f[0].isBlank()||f[1].isBlank()||pandasMissing(f[0])||pandasMissing(f[1])||!Set.of("+","-").contains(f[2]))throw new IOException("Invalid literal gene/contig/strand; no pandas missing-identifier conversion");if(first==null)first=f[1];long start=coordinate(f[3]),end=coordinate(f[4]);if(start>=end)throw new IOException("Annotation transcript interval is empty/reversed");String[] a=f[5].split(",",-1),b=f[6].split(",",-1);if(a.length<2||a.length!=b.length||!a[a.length-1].isEmpty()||!b[b.length-1].isEmpty())throw new IOException("Original annotation requires equal comma-terminated exon lists");long previous=-1;for(int i=0;i<a.length-1;i++){long x=coordinate(a[i]),y=coordinate(b[i]);if(x<start||y>end||x>=y||x<previous)throw new IOException("Invalid original exon coordinates/order");previous=y;if(++exons>SpliceAiToolsRequest.number(r,"maximum_annotations"))throw new IOException("Complete annotation exon capacity exceeded");}if(++rows>SpliceAiToolsRequest.number(r,"maximum_annotations"))throw new IOException("Complete gene annotation capacity exceeded");}}
        if(rows==0)throw new IOException("Original gene annotation is empty");return Map.of("gene_context_rows",rows,"exons",exons,"first_source_CHROM",first,"transcript_and_exon_starts_zero_based",true,"ends_one_based_inclusive",true,"duplicate_gene_contexts_retained",true,"transcript_edition_inferred",false);
    }
    private static long coordinate(String raw)throws IOException{if(!raw.matches("0|[1-9][0-9]*"))throw new IOException("Invalid literal annotation integer");try{return Long.parseLong(raw);}catch(NumberFormatException e){throw new IOException("Annotation coordinate overflow",e);}}
    private static boolean pandasMissing(String value){return Set.of("NA","N/A","NaN","nan","NULL","null","None","<NA>","#N/A","#N/A N/A","#NA","-NaN","-nan","1.#IND","-1.#IND","1.#QNAN","-1.#QNAN").contains(value);}
}
